"""The published script channel artifact is generated by the native producer."""

import json
from pathlib import Path

from agent_core.domain.runtime_bundle_json import json_digest
from zebra_agent_api.script_publication_contract import script_publication_contract


def test_exact_producer_contract_and_digest():
    artifact = json.loads(Path("docs/contracts/script-publication/contract.json").read_bytes())
    assert artifact == script_publication_contract()
    assert artifact["contractDigest"] == json_digest(
        {k: v for k, v in artifact.items() if k != "contractDigest"}
    )
    assert not any(artifact["capabilities"].values())
    assert artifact["materialize"]["definition"] == "agent-definition/3"
